func wifi_server_main() {
	time.Sleep(2 * time.Second)
	if ssid == "" {
		wifi_server_failure("ssid is empty: build with -ldflags=\"-X main.ssid=... -X main.password=...\"")
	}

	sensor := badge.NewSensor()
	go func() {
		for {
			err := sensor.Read()
			wifi_server_mu.Lock()
			wifi_server_readErr = err
			if err == nil {
				wifi_server_deciTemp = sensor.DeciCelsius()
				wifi_server_deciHum = sensor.DeciRelHumidity()
				wifi_server_readAt = time.Now()
			}
			wifi_server_mu.Unlock()
			time.Sleep(2 * time.Second)
		}
	}()

	// 接続に失敗した場合はリセットして最初からやり直す (成功するまで戻らない)
	link := &link.Esplink{}
	netdev.UseNetdev(link)
	wifi.Connect(link, ssid, password)

	var mux httphi.MuxSlice
	mux.Handle("/", wifi_server_logRequest(wifi_server_index))
	mux.Handle("/api", wifi_server_logRequest(wifi_server_api))
	mux.Handle("/metrics", wifi_server_logRequest(wifi_server_metrics))

	var router httphi.Router
	cfg := httphi.DefaultRouterConfig(4, 2048, mux.MaxPathValues())
	wifi_server_failIfErr("router configure", router.Configure(&mux, cfg))
	defer router.Shutdown()

	addr, err := link.Addr()
	wifi_server_failIfErr("link.Addr", err)
	print("HTTP server listening on http://", addr.String(), ":", wifi_server_port, "\n")
	wifi_server_failIfErr("ListenAndServe", link.ListenAndServe(&router, wifi_server_port))
}

