// appendDeci は 0.1 単位の整数を "12.3" 形式で追記する。
func wifi_server_appendDeci(b []byte, v int32) []byte {
	if v < 0 {
		b = append(b, '-')
		v = -v
	}
	b = strconv.AppendInt(b, int64(v/10), 10)
	b = append(b, '.')
	return strconv.AppendInt(b, int64(v%10), 10)
}

